// Convert Polygon2d to CGAL polygons
internal::Polygon_2 cgal_p1, cgal_p2;

// Fill first polygon
for (unsigned int i = 0; i < P1.size(); ++i) {
    const Point2d& p = P1[i];
    cgal_p1.push_back(internal::Point_2(p.x(), p.y()));
}

// Fill second polygon
for (unsigned int i = 0; i < P2.size(); ++i) {
    const Point2d& p = P2[i];
    cgal_p2.push_back(internal::Point_2(p.x(), p.y()));
}

// Perform difference operation
internal::Pwh_list_2 diff_result;
CGAL::difference(cgal_p1, cgal_p2, std::back_inserter(diff_result));

// Convert result back to our polygon format
std::vector<PolygonWithHoles2d> result;
result.reserve(diff_result.size());

for (const internal::Polygon_with_holes_2& pwh : diff_result) {
    // Extract outer boundary
    std::vector<Point2d> outer_boundary;
    outer_boundary.reserve(pwh.outer_boundary().size());
    for (const internal::Point_2& cp : pwh.outer_boundary()) {
        double x, y;
        internal::getCoordinates(cp, x, y);
        outer_boundary.emplace_back(x, y);
    }

    // Extract holes
    std::vector<std::vector<Point2d>> holes;
    holes.reserve(pwh.holes_begin()->size());
    for (auto hit = pwh.holes_begin(); hit != pwh.holes_end(); ++hit) {
        std::vector<Point2d> hole;
        hole.reserve(hit->size());
        for (const internal::Point_2& cp : *hit) {
            double x, y;
            internal::getCoordinates(cp, x, y);
            hole.emplace_back(x, y);
        }
        holes.push_back(hole);
    }

    result.emplace_back(outer_boundary, holes);
}

return result;

